head.script:
(function () {
  var pageviewId =
    window.crypto && crypto.randomUUID ? crypto.randomUUID() : null;

  if (pageviewId) {
    /*
     * advert-xandr.js reads the pageview id from window.openDataLayer, so it
     * must be exposed before gtm.js and advert-xandr.js execute (FREE-5107).
     * The same id is written to dataLayer[0].pageview_id below: the dataLayer
     * is initialized by our back-end, so the server-rendered entry is always
     * the first entry. Legacy browsers without crypto.randomUUID fall back to
     * the GTM-generated pageview_id (allowed for <1% of page loads).
     */
    window.openDataLayer = window.openDataLayer || {};
    window.openDataLayer.pageViewId = pageviewId;
  }

  var entry = dataLayer.find(function (item) {
    return item["pageview_id"] === "" && !!item["user"];
  });

  if (!entry) {
    return;
  }

  if (
    App.config.user &&
    App.config.user.id &&
    typeof entry.user === "object"
  ) {
    entry.user.account_id = App.config.user.id;
  }

  if (pageviewId) {
    entry.pageview_id = pageviewId;
  }
})();

