body.script:
(function () {

	var baitPath = "https:\/\/t.hln.be"+'/ads-min.js';
	var pixelPath = "https:\/\/t.hln.be"+'/4dchk';


	// Inject the bait file
	var el = document.createElement('script');
	el.src = baitPath;
	document.body.appendChild(el);

	// this function pre-fetches the SP JS. If that doesn't work, it means it's blocked
	function isSpBlocked() {
		return fetch("https://sp.dpgmedia.net/Cd47FPkRXzy5tMeertNeUPW_v3.js", {
			method: "HEAD",
			mode: "no-cors"
		}).then(function () {
			return false;
		}).catch(function () {
			return true;
		})
	}

	// this function pre-fetches the GA JS. If that doesn't work, it means it's blocked
	function isGaBlocked() {
		return fetch("https://www.google-analytics.com/analytics.js", {
			method: "HEAD",
			mode: "no-cors"
		}).then(function () {
			return false
		}).catch(function () {
				return true
			});
	};

	function getSPCookie() {
		var cookieStart = '_sp_id';
		var match = document.cookie.match(new RegExp(cookieStart + '.([^;]+)=([^;]+)'));
		if (match && match.length > 2) {
			return match[2];
		}

		return '';
	};

	window.addEventListener('load', function () {
		// we try to fetch the ga and sp files together. They will return true if they're blocked, false if they work
		Promise.all([isGaBlocked(), isSpBlocked()]).then(function ([gaBlocked, spBlocked]) {
			// Build the GA4 parameters, add additional parameters at your leisure
			var adsBlocked = !document.querySelector("#GxsCRdhiJi");
			var gtmBlocked = !(window.google_tag_manager && window.google_tag_manager.dataLayer);

			if (!gaBlocked && !spBlocked && !adsBlocked && !gtmBlocked) return;

			var params = {
				ads_blocked: adsBlocked, // Detect if the bait file was blocked
				gtm_blocked: gtmBlocked, // Detect if gtm.js was blocked
				ga_blocked: gaBlocked, // Detect if analytics.js was blocked
				sp_blocked: spBlocked // Detect if SP was blocked
			};

			// Build the pixel request with a unique, random Client ID
			var duid = getSPCookie(); //get cookie value that starts with _sp_id. and is placed on main domain
			var cid = Math.floor(Math.random() * 1000000 + 1) + "_" + new Date().getTime();
			var img = document.createElement("img");
			img.style = "width: 1; height: 1; display: none;";
			img.src =
				pixelPath +
				"?client_id=" +
				cid +
				"&duid=" +
				duid +
				"&" +
				Object.keys(params)
					.reduce(function (acc, cur) {
						return acc.concat(cur + "=" + params[cur]);
					}, [])
					.join("&");
			document.body.appendChild(img);
		});
	});
})();
